  --card-foreground: var(--foreground);
  --popover: var(--panel);
  --popover-foreground: var(--foreground);
  --line: oklch(0.8 0.02 85.7); /* #c3bdb0 */
  --line-strong: oklch(0.68 0.025 84.6); /* #9f9787 */
  --border: var(--line);
  --muted: var(--w-bone-200);
  --muted-foreground: var(--w-ink-500);
  --primary: var(--w-blue-deep);
  --primary-foreground: var(--w-bone-50);
  --accent: var(--primary);
  --accent-foreground: var(--primary-foreground);
  --secondary: var(--w-bone-200);
  --secondary-foreground: var(--foreground);
  --destructive: var(--w-ochre-deep);
  --destructive-foreground: var(--w-bone-50);
  --input: var(--line-strong);
  --ring: var(--w-blue-deep);
  --ochre: var(--w-ochre-deep);
  --wheat: var(--w-wheat-deep);
  --sage: var(--w-sage-deep);

  --grid-minor: color-mix(in oklab, var(--foreground) 4%, transparent);
  --grid-major: color-mix(in oklab, var(--foreground) 8%, transparent);
  --grid-dot: color-mix(in oklab, var(--w-blue-deep) 20%, transparent);
}

