  --w-c-button-fg: var(--foreground);
  --w-c-button-line: var(--line-strong);
  --w-c-button-bg-hover: var(--panel-soft);
  --w-c-button-primary-bg: var(--primary);
  --w-c-button-primary-fg: var(--primary-foreground);

  /* input */
  --w-c-input-bg: var(--background);
  --w-c-input-line: var(--line-strong);
  --w-c-input-line-focus: var(--ring);

  /* badge */
  --w-c-badge-bg: var(--panel-soft);
