  --w-c-selection: color-mix(in oklab, var(--primary) 28%, transparent);
  --w-hairline: 0 0 0 1px var(--line);
  --w-hairline-strong: 0 0 0 1px var(--line-strong);

  /* radius — IDE 风：更方 */
  --w-radius: 3px;
  --w-radius-sm: 2px;
}

