 * build:  pnpm tokens:build
 */

/* Usage:
 *   @import "tailwindcss";
 *   @import "@weed/tokens/tailwind.css";   ← this file
 * 颜色全部指向语义变量，data-theme 切换零配置。
 */

@theme inline {
  /* shadcn-compatible surface */
  --color-background: var(--background);
  --color-foreground: var(--foreground);
  --color-card: var(--card);
  --color-card-foreground: var(--card-foreground);
  --color-popover: var(--popover);
  --color-popover-foreground: var(--popover-foreground);
  --color-primary: var(--primary);
  --color-primary-foreground: var(--primary-foreground);
  --color-secondary: var(--secondary);
  --color-secondary-foreground: var(--secondary-foreground);
  --color-muted: var(--muted);
  --color-muted-foreground: var(--muted-foreground);
  --color-accent: var(--accent);
  --color-accent-foreground: var(--accent-foreground);
  --color-destructive: var(--destructive);
  --color-destructive-foreground: var(--destructive-foreground);
  --color-border: var(--border);
  --color-input: var(--input);
  --color-ring: var(--ring);

  /* weed extensions */
  --color-panel: var(--panel);
  --color-panel-soft: var(--panel-soft);
  --color-panel-foreground: var(--panel-foreground);
  --color-line: var(--line);
  --color-line-strong: var(--line-strong);
  --color-ochre: var(--ochre);
  --color-wheat: var(--wheat);
  --color-sage: var(--sage);

  /* fonts */
  --font-mono: var(--w-font-mono);
  --font-serif: var(--w-font-serif);

  /* radii — small, engineering-manual */
  --radius-sm: var(--w-radius-sm);
  --radius-md: var(--w-radius);
  --radius-lg: calc(var(--w-radius) + 2px);
}

import { clsx, type ClassValue } from "clsx";
import { twMerge } from "tailwind-merge";

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

import * as React from "react";
import { cva, type VariantProps } from "class-variance-authority";

import { cn } from "@/lib/utils";

const buttonVariants = cva(
  "inline-flex items-center justify-center gap-1.5 whitespace-nowrap rounded-[3px] font-mono text-[11px] uppercase tracking-[0.1em] transition-colors focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-ring disabled:pointer-events-none disabled:opacity-40 [&_svg]:size-3.5 [&_svg]:shrink-0",
  {
    variants: {
      variant: {
        default:
          "bg-primary text-primary-foreground hover:brightness-110 active:brightness-95",
        outline:
          "bg-panel text-foreground shadow-[inset_0_0_0_1px_var(--w-c-button-line)] hover:bg-panel-soft hover:shadow-[inset_0_0_0_1px_var(--foreground)]",
        ghost:
          "text-muted-foreground hover:bg-panel-soft hover:text-foreground",
        subtle:
          "bg-panel-soft text-muted-foreground hover:text-foreground hover:bg-panel",
      },
      size: {
        sm: "h-6 px-2",
        default: "h-7 px-3",
        lg: "h-9 px-5 text-xs",
        icon: "size-7",
      },
    },
    defaultVariants: {
      variant: "outline",
      size: "default",
    },
  }
);

function Button({
  className,
  variant,
  size,
  ...props
}: React.ComponentProps<"button"> & VariantProps<typeof buttonVariants>) {
  return (
    <button
      data-slot="button"
      className={cn(buttonVariants({ variant, size, className }))}
      {...props}
    />
  );
}

export { Button, buttonVariants };

import { clsx, type ClassValue } from "clsx";
import { twMerge } from "tailwind-merge";

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

