/* ---------------------------------------------------------------- */
/* blueprint grid                                                    */
/* ---------------------------------------------------------------- */
.w-blueprint {
  position: relative;
  background-color: var(--background);
  isolation: isolate;
}

.w-blueprint::before {
  content: "";
  position: absolute;
  inset: 0;
  z-index: -1;
  pointer-events: none;

  background-image:
    /* cross dots at major intersections */
    radial-gradient(var(--grid-dot) 0.8px, transparent 1.2px),
    /* minor grid — 20px */
    linear-gradient(to right, var(--grid-minor) 1px, transparent 1px),
    linear-gradient(to bottom, var(--grid-minor) 1px, transparent 1px),
    /* major grid — 100px, 双档线重 */
    linear-gradient(to right, var(--grid-major) 1px, transparent 1px),
    linear-gradient(to bottom, var(--grid-major) 1px, transparent 1px);

  background-size:
    100px 100px,
    20px 20px,
    20px 20px,
    100px 100px,
    100px 100px;

  background-position:
    -0.5px -0.5px,
    0 0,
    0 0,
    0 0,
    0 0;

  -webkit-mask-image: var(--grid-fade);
  mask-image: var(--grid-fade);
}

/* full-bleed variant: gentler fade */
.w-blueprint--flat::before {
  -webkit-mask-image: radial-gradient(
    ellipse 140% 100% at 50% 0%,
    black 0%,
    black 45%,
    transparent 90%
  );
  mask-image: radial-gradient(
    ellipse 140% 100% at 50% 0%,
    black 0%,
    black 45%,
    transparent 90%
  );
}

